# for pending rows), requests to manage a profile (Flow B), history for invitations and
# requests, TR-16 step-up verifications, and the Owner-only reclassification of
# manage_family_authorizations and manage_verification_submission (OD-05c).
TTL_DAYS = 30
OWNER_ONLY = ("manage_family_authorizations", "manage_verification_submission")


def backfill_expiry(apps, schema_editor):
    from datetime import timedelta

    Invitation = apps.get_model("family", "ManagerInvitation")
    Authorization = apps.get_model("family", "ProfileManagerAuthorization")
    for invitation in Invitation.objects.filter(expires_at__isnull=True):
        invitation.expires_at = invitation.invited_at + timedelta(days=TTL_DAYS)
        invitation.save(update_fields=["expires_at"])
        if invitation.authorization_id:
            Authorization.objects.filter(
                pk=invitation.authorization_id, status="PENDING", invitation_expires_at__isnull=True
            ).update(invitation_expires_at=invitation.expires_at)


def owner_only(apps, schema_editor):
    Permission = apps.get_model("family", "ManagerPermission")
    Permission.objects.filter(code__in=OWNER_ONLY).update(sensitivity="OWNER_ONLY")


def sensitive_again(apps, schema_editor):
    Permission = apps.get_model("family", "ManagerPermission")
    Permission.objects.filter(code__in=OWNER_ONLY).update(sensitivity="SENSITIVE")


